from datetime import datetime, timezone
from botocore.exceptions import ClientError
from cloud_clients import create_resilient_client


class OrderRepository:
    def __init__(self, table_name: str) -> None:
        self.table_name = table_name
        self.client = create_resilient_client(
            "dynamodb"
        )

    def create_order_idempotent(
        self,
        order_id: str,
        customer_id: str,
        amount_cents: int,
    ) -> dict[str, str]:
        """Insert a new order only if order_id does not
        already exist. Safely handles duplicate calls.
        """
        now_iso = datetime.now(
            timezone.utc
        ).isoformat()

        try:
            self.client.put_item(
                TableName=self.table_name,
                Item={
                    "pk": {"S": f"ORDER#{order_id}"},
                    "sk": {"S": "METADATA"},
                    "customer_id": {"S": customer_id},
                    "amount_cents": {
                        "N": str(amount_cents)
                    },
                    "status": {"S": "PENDING"},
                    "version": {"N": "1"},
                    "updated_at": {"S": now_iso},
                },
                ConditionExpression=(
                    "attribute_not_exists(pk)"
                ),
            )
            return {
                "order_id": order_id,
                "status": "CREATED",
            }
        except ClientError as exc:
            code = exc.response["Error"]["Code"]
            if (
                code
                == "ConditionalCheckFailedException"
            ):
                # Idempotent replay: order exists
                return {
                    "order_id": order_id,
                    "status": "ALREADY_EXISTS",
                }
            raise

    def transition_order_status(
        self,
        order_id: str,
        expected_version: int,
        new_status: str,
    ) -> int:
        """Optimistic locking update: bumps version
        atomically only if current version matches.
        """
        next_ver = expected_version + 1
        now_iso = datetime.now(
            timezone.utc
        ).isoformat()

        self.client.update_item(
            TableName=self.table_name,
            Key={
                "pk": {"S": f"ORDER#{order_id}"},
                "sk": {"S": "METADATA"},
            },
            UpdateExpression=(
                "SET #st = :new_st, "
                "#ver = :next_ver, "
                "updated_at = :now"
            ),
            ConditionExpression="#ver = :exp_ver",
            ExpressionAttributeNames={
                "#st": "status",
                "#ver": "version",
            },
            ExpressionAttributeValues={
                ":new_st": {"S": new_status},
                ":exp_ver": {
                    "N": str(expected_version)
                },
                ":next_ver": {"N": str(next_ver)},
                ":now": {"S": now_iso},
            },
        )
        return next_ver

